parameters.jsCode:
// The API groups its answer by result date:
//   { data: { "2026-09-07": [ { finCode, compName, nseSymbol, bseSymbol, ... } ] } }
// Flatten that to one item per stock and keep only what the MCP lookup needs.
//
// NSE symbols here carry the trading *series* suffix - DHTL-SM (SME board),
// KOTYARK-BE (book entry), also -BZ / -BL / -ST / -IL / -RT. screener.in knows
// the bare ticker only: /company/DHTL-SM/ is a 404 and /company/DHTL/ is not,
// so the suffix is stripped before anything is looked up.
const SERIES = /-(SM|ST|BE|BZ|BL|IL|RT|GB|GS|MF|IV|EQ|N[0-9]|W[0-9]|Y[0-9])$/i;

// Only a symbol matching this may reach the shell in the next node.
const SAFE = /^[A-Za-z0-9][A-Za-z0-9&.\-]{0,30}$/;

const runId = new Date().toISOString().replace(/[-:]/g, '').replace(/\..+$/, 'Z');
const out = [];

for (const item of $input.all()) {
  // fullResponse is on, so the document is under body and the status is visible.
  const status = item.json?.statusCode ?? null;
  const body = item.json?.body ?? item.json ?? {};
  const buckets = body?.data ?? null;

  if (status !== null && (status < 200 || status >= 300)) {
    out.push({ json: { runId, usable: false, company: null, symbol: null, rawSymbol: null,
      exchange: null, finCode: null, resultDate: null,
      skipReason: `the upcoming-results API answered HTTP ${status}`,
      apiRecord: { statusCode: status, body: JSON.stringify(body).slice(0, 1000) } } });
    continue;
  }

  if (!buckets || typeof buckets !== 'object') {
    out.push({ json: { runId, usable: false, company: null, symbol: null, rawSymbol: null,
      exchange: null, finCode: null, resultDate: null,
      skipReason: 'the upcoming-results API returned no data object',
      apiRecord: { statusCode: status, body: JSON.stringify(body).slice(0, 1000) } } });
    continue;
  }

  for (const [resultDate, rows] of Object.entries(buckets)) {
    for (const row of Array.isArray(rows) ? rows : []) {
      const raw = String(row.nseSymbol ?? row.bseSymbol ?? '').trim();
      const symbol = raw.replace(SERIES, '').toUpperCase();
      const usable = SAFE.test(symbol);
      out.push({ json: {
        runId,
        resultDate,
        finCode: row.finCode ?? null,
        company: row.compName ?? null,
        rawSymbol: raw || null,
        symbol,
        exchange: row.nseSymbol ? 'NSE' : (row.bseSymbol ? 'BSE' : null),
        details: String(row.details ?? '').trim() || null,
        usable,
        skipReason: usable ? null
          : (raw ? `"${raw}" does not reduce to a plain ticker` : 'the record carries no nseSymbol or bseSymbol'),
        // kept whole so a failure can be replayed against the exact input
        apiRecord: row,
      } });
    }
  }
}

if (out.length === 0) {
  return [{ json: { runId, usable: false, company: null, symbol: null, rawSymbol: null,
    exchange: null, finCode: null, resultDate: null,
    skipReason: 'the upcoming-results API listed no stocks', apiRecord: null } }];
}
return out;

parameters.command:
=# One screener MCP call per stock: the quarterly results table.
#
# The script is inlined with node -e and therefore lives inside a shell
# single-quoted string - it deliberately contains no single quote of its own.
# SYMBOL is empty for any stock the flatten step could not reduce to a plain
# ticker, and the script reports that as an error rather than querying junk.
# It never exits non-zero and always prints exactly one JSON document.

SYMBOL="{{ $json.usable ? $json.symbol : "" }}" \
MCP_ENDPOINT="http://127.0.0.1:3123/mcp" \
MCP_TIMEOUT_MS=30000 \
node -e 'const ep = process.env.MCP_ENDPOINT || "http://127.0.0.1:3123/mcp";
const sym = process.env.SYMBOL || "";
const ms = Number(process.env.MCP_TIMEOUT_MS || 30000);
const emit = (o) => process.stdout.write(JSON.stringify(o));
const call = async (consolidated) => {
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), ms);
  try {
    const r = await fetch(ep, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json, text/event-stream", "Cache-Control": "no-cache" },
      body: JSON.stringify({ jsonrpc: "2.0", id: Date.now(), method: "tools/call", params: { name: "screener_get_financial_statement", arguments: { identifier: sym, statement: "quarters", consolidated: consolidated } } }),
      signal: ac.signal
    });
    const body = await r.text();
    if (!r.ok) return { ok: false, error: "MCP HTTP " + r.status, raw: body.slice(0, 400) };
    const s = body.trim();
    let env = null;
    if (s.charAt(0) === "{") { env = JSON.parse(s); }
    else {
      const lines = s.split(/\r?\n/).filter((l) => l.indexOf("data:") === 0);
      if (lines.length === 0) return { ok: false, error: "unparseable MCP response", raw: s.slice(0, 400) };
      env = JSON.parse(lines[lines.length - 1].slice(5).trim());
    }
    if (env.error) return { ok: false, error: "RPC " + (env.error.message || JSON.stringify(env.error)) };
    const res = env.result || {};
    const text = (res.content || []).map((c) => c.text || "").join("\n").trim();
    if (res.isError) return { ok: false, error: text.split("\n")[0] || "tool reported an error", raw: text.slice(0, 400) };
    return { ok: true, structured: res.structuredContent, text: text };
  } catch (e) {
    const msg = e && e.name === "AbortError" ? "timed out after " + ms + "ms" : String((e && e.message) || e);
    return { ok: false, error: "REQUEST FAILED: " + msg };
  } finally { clearTimeout(timer); }
};
const isEmpty = (x) => Boolean(x.ok && x.structured && Array.isArray(x.structured.periods) && x.structured.periods.length === 0);
(async () => {
  if (!sym) { emit({ ok: false, symbol: sym, error: "no usable symbol was supplied for this stock" }); return; }
  let res = await call(true);
  let variant = "consolidated";
  if (!res.ok || isEmpty(res)) {
    const alt = await call(false);
    if (alt.ok && !isEmpty(alt)) { res = alt; variant = "standalone"; }
  }
  emit({ ok: res.ok, symbol: sym, variant: variant, error: res.error || null, structured: res.structured, text: res.text, raw: res.raw });
})();'

parameters.jsCode:
// Parse every MCP answer into JSON, then keep only the stocks whose quarterly
// table actually carries the target column. Runs once for all items and returns
// a single item: the log writer downstream must fire once, not once per stock.
//
// >>> The one line to change when the quarter rolls over: <<<
const TARGET_PERIOD = 'Sep 2026';

const stocks = $('Flatten Upcoming Results').all().map((i) => i.json);
const replies = $input.all().map((i) => i.json);
const ts = new Date().toISOString();
const runId = stocks[0]?.runId ?? ts.replace(/[-:]/g, '').replace(/\..+$/, 'Z');

// --------------------------------------------------------------------------
// The parser.
//
// The MCP server answers with Markdown in content[].text and the same table as
// JSON in structuredContent. structuredContent is preferred; the Markdown
// parser below is the fallback for when it is absent, so a statement always
// reaches the filter in one shape no matter which form the server sent.
// --------------------------------------------------------------------------
const splitRow = (line) => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
const isSeparator = (cells) => cells.length > 0 && cells.every((c) => /^:?-{2,}:?$/.test(c));

function parseMarkdownTable(text) {
  if (!text) return null;
  const lines = String(text).split(/\r?\n/);
  const heading = lines.find((l) => /^#{1,6}\s/.test(l.trim()));
  const pipeRows = lines.filter((l) => l.trim().startsWith('|')).map(splitRow);
  const sepAt = pipeRows.findIndex(isSeparator);
  if (sepAt < 1) return null; // no header row above a separator: not a table
  return {
    section: heading ? heading.trim().replace(/^#+\s*/, '') : null,
    periods: pipeRows[sepAt - 1].slice(1).filter((h) => h !== ''),
    rows: pipeRows.slice(sepAt + 1)
      .map((c) => ({ label: c[0] ?? null, values: c.slice(1) }))
      .filter((r) => r.label),
    via: 'markdown',
  };
}

function toStatement(reply) {
  const sc = reply?.structured;
  if (sc && Array.isArray(sc.periods)) {
    return { section: sc.section ?? null, periods: sc.periods, rows: sc.rows ?? [], via: 'structuredContent' };
  }
  return parseMarkdownTable(reply?.text);
}

// [{label, values}] -> {label: values}, padded to the period count, so a line
// item is addressable by name and every row lines up with `periods`.
function rowsToObject(rows, periods) {
  const out = {};
  for (const row of Array.isArray(rows) ? rows : []) {
    if (!row?.label) continue;
    const values = Array.isArray(row.values) ? row.values : [];
    out[row.label] = periods.map((_, i) => (values[i] === undefined || values[i] === '' ? null : values[i]));
  }
  return out;
}

// "Sept 2026" and " sep 2026 " name the same column as "Sep 2026".
const key = (p) => String(p).replace(/\s+/g, ' ').trim().toLowerCase().replace(/^sept\b/, 'sep');
const samePeriod = (a, b) => key(a) === key(b);

// --------------------------------------------------------------------------
const qualified = [];
const failures = [];

for (let i = 0; i < stocks.length; i++) {
  const stock = stocks[i];
  const who = {
    runId,
    company: stock.company,
    symbol: stock.symbol || null,
    rawSymbol: stock.rawSymbol,
    exchange: stock.exchange,
    finCode: stock.finCode,
    resultDate: stock.resultDate,
  };

  // 1. never reached the MCP server at all
  if (!stock.usable) {
    failures.push({ ts, event: 'skipped', stage: 'symbol', ...who,
      reason: stock.skipReason, error: null, payload: { apiRecord: stock.apiRecord } });
    continue;
  }

  // 2. the shell / transport layer
  const raw = replies[i];
  let reply = null;
  try {
    const stdout = String(raw?.stdout ?? '').trim();
    if (!stdout) throw new Error('the query printed nothing (exit ' + (raw?.exitCode ?? '?') + ')');
    const at = stdout.indexOf('{');
    if (at < 0) throw new Error('no JSON document on stdout');
    reply = JSON.parse(stdout.slice(at));
  } catch (err) {
    failures.push({ ts, event: 'failed', stage: 'mcp-query', ...who,
      reason: 'the MCP query produced no parseable JSON',
      error: err.message,
      payload: {
        exitCode: raw?.exitCode ?? null,
        stdout: String(raw?.stdout ?? '').slice(0, 800),
        stderr: String(raw?.stderr ?? '').slice(-800),
        apiRecord: stock.apiRecord,
      } });
    continue;
  }

  // Execute Command emits one output item per input item, in order, so index i
  // pairs them. Guard the assumption rather than trusting it silently.
  if (reply.symbol && reply.symbol !== stock.symbol) {
    failures.push({ ts, event: 'failed', stage: 'pairing', ...who,
      reason: 'the MCP answer did not belong to this stock',
      error: 'expected ' + stock.symbol + ', the query answered for ' + reply.symbol,
      payload: { reply, apiRecord: stock.apiRecord } });
    continue;
  }

  // 3. the tool itself
  if (!reply.ok) {
    failures.push({ ts, event: 'failed', stage: 'mcp-tool', ...who,
      reason: 'the screener MCP server could not return quarterly results',
      error: reply.error ?? null,
      payload: { variant: reply.variant ?? null, raw: String(reply.raw ?? '').slice(0, 600), apiRecord: stock.apiRecord } });
    continue;
  }

  // 4. the parser
  const statement = toStatement(reply);
  if (!statement) {
    failures.push({ ts, event: 'failed', stage: 'parse', ...who,
      reason: 'the answer held neither structuredContent nor a Markdown table',
      error: null,
      payload: { variant: reply.variant ?? null, text: String(reply.text ?? '').slice(0, 600), apiRecord: stock.apiRecord } });
    continue;
  }

  // 5. the filter - the whole point of this workflow
  const periods = Array.isArray(statement.periods) ? statement.periods : [];
  const matched = periods.find((p) => samePeriod(p, TARGET_PERIOD)) ?? null;

  if (!matched) {
    failures.push({ ts, event: 'not-qualified', stage: 'filter', ...who,
      reason: periods.length === 0
        ? 'screener has no quarterly table for this stock yet, so it cannot have a "' + TARGET_PERIOD + '" column'
        : 'the quarterly table has no "' + TARGET_PERIOD + '" column',
      error: null,
      payload: { via: statement.via, variant: reply.variant ?? null, periods, apiRecord: stock.apiRecord } });
    continue;
  }

  qualified.push({ ts, ...who,
    matchedPeriod: matched,
    targetPeriod: TARGET_PERIOD,
    via: statement.via,
    variant: reply.variant ?? null,
    quarters: { section: statement.section, periods, rows: rowsToObject(statement.rows, periods) },
  });
}

// --------------------------------------------------------------------------
// Log lines. The qualified log is deliberately slim - the full quarterly table
// travels in the workflow output, not into a file that grows every 5 minutes.
const qualifiedLog = qualified.map((q) => ({
  ts: q.ts, runId, event: 'qualified', company: q.company, symbol: q.symbol,
  rawSymbol: q.rawSymbol, exchange: q.exchange, finCode: q.finCode,
  resultDate: q.resultDate, matchedPeriod: q.matchedPeriod,
  periods: q.quarters.periods, via: q.via, variant: q.variant,
}));

const count = (e) => failures.filter((f) => f.event === e).length;
const summary = {
  ts, runId, targetPeriod: TARGET_PERIOD, checked: stocks.length,
  qualified: qualified.length, notQualified: count('not-qualified'),
  failed: count('failed'), skipped: count('skipped'),
};

const jsonl = (arr) => arr.map((o) => JSON.stringify(o)).join('\n');

return [{ json: {
  ok: true,
  ...summary,
  results: qualified,
  failures,
  logs: {
    qualifiedJsonl: jsonl(qualifiedLog),
    failuresJsonl: jsonl(failures),
    runJsonl: JSON.stringify(summary),
  },
} }];

// Fan the run back out to one item per qualifying stock.
//
// Read from the classifier rather than from $input: the log writer sits between
// them and Execute Command replaces the item with {exitCode, stdout, stderr}.
const run = $('Filter On Sep 2026 Column').first().json;
const logged = $input.first().json;

const base = {
  ok: true,
  runId: run.runId,
  ts: run.ts,
  targetPeriod: run.targetPeriod,
  logWritten: (logged?.exitCode ?? 0) === 0,
  logDir: '/home/node/.n8n/univest-results/logs',
};

// Nothing qualified is a normal outcome, not an error - most runs will land
// here until companies start filing the target quarter. The run summary still
// comes out so the caller can see what was checked.
if (!Array.isArray(run.results) || run.results.length === 0) {
  return [{ json: {
    ...base,
    qualified: 0,
    reason: 'no stock has a "' + run.targetPeriod + '" column yet',
    checked: run.checked,
    notQualified: run.notQualified,
    failed: run.failed,
    skipped: run.skipped,
    failures: run.failures,
  } }];
}

return run.results.map((stock) => ({ json: { ...base, ...stock } }));

// The MCP server never answered tools/list, so not one stock could be checked.
// That is a run-level failure and belongs in the same failures.jsonl as the
// per-stock ones, with the tail of the server log as the payload it failed for.
//
// The record is built here rather than inside an expression on the shell node:
// an object literal inside {{ }} is exactly the thing older n8n expression
// parsers get wrong, and a log writer that silently emits nothing is worse than
// no log writer at all.
const ts = new Date().toISOString();
const runId = ts.replace(/[-:]/g, '').replace(/\..+$/, 'Z');
const mcpLog = String($input.first().json?.stdout ?? '').slice(-1500);

const record = {
  ts,
  runId,
  event: 'failed',
  stage: 'mcp-health',
  company: null,
  symbol: null,
  rawSymbol: null,
  exchange: null,
  finCode: null,
  resultDate: null,
  reason: 'the screener MCP server did not answer tools/list, so no stock was checked',
  error: mcpLog.split('\n').filter(Boolean).slice(-1)[0] ?? 'no output from the MCP log',
  payload: { endpoint: 'http://127.0.0.1:3123/mcp', mcpLogTail: mcpLog },
};

return [{ json: {
  ok: false,
  ...record,
  logLine: JSON.stringify(record),
  runLine: JSON.stringify({ ts, runId, targetPeriod: null, checked: 0, qualified: 0, notQualified: 0, failed: 1, skipped: 0 }),
} }];

// Terminal state for the unhealthy branch: a parseable failure document, so a
// caller (or the supervisor) never has to tell "MCP was down" apart from
// "the workflow produced nothing".
const failure = $('Build Health Failure').first().json;
const written = $input.first().json;

return [{ json: {
  ok: false,
  stage: 'mcp-health',
  runId: failure.runId,
  ts: failure.ts,
  error: 'screener MCP server is not answering tools/list on http://127.0.0.1:3123/mcp',
  reason: failure.reason,
  mcpLogTail: failure.payload?.mcpLogTail ?? null,
  logWritten: (written?.exitCode ?? 0) === 0,
  logDir: '/home/node/.n8n/univest-results/logs',
} }];
